```java
// ─── File: DbUsersDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.dbusers;

import java.util.*;
import java.util.logging.*;

public class DbUsersDemo {
    private static final Logger log = Logger.getLogger("RDSUsers");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DatabaseUserManager mgr = new DatabaseUserManager("nbi_master");

        DbUser transferApp = mgr.createUser("transfer_app", Set.of("SELECT", "INSERT", "UPDATE"));
        DbUser reportRo = mgr.createUser("report_ro", Set.of("SELECT"));
        log.info(() -> "Created " + transferApp.name() + " grants=" + transferApp.privileges());
        log.info(() -> "Created " + reportRo.name() + " grants=" + reportRo.privileges());

        log.severe(() -> "Attempt to use master for app: " + mgr.assertNotMaster("nbi_master"));
        log.info(() -> "Using dedicated user for app: " + mgr.assertNotMaster("transfer_app"));

        IamAuthenticator iam = new IamAuthenticator();
        log.info(() -> "IAM token for transfer_app: " + iam.generateToken("transfer_app") + " (expires ~15 min)");

        // report_ro trying to write must be denied.
        log.warning(() -> "report_ro INSERT allowed? " + reportRo.can("INSERT"));
        log.info(() -> "report_ro SELECT allowed? " + reportRo.can("SELECT"));
    }
}

// ─── Would be in DatabaseUserManager.java ───
class DatabaseUserManager {
    private final String masterUser;
    private final Map<String, DbUser> users = new HashMap<>();
    DatabaseUserManager(String masterUser) { this.masterUser = masterUser; }

    // Equivalent to CREATE USER ... GRANT <privileges>.
    DbUser createUser(String name, Set<String> privileges) {
        DbUser u = new DbUser(name, privileges);
        users.put(name, u);
        return u;
    }

    // Applications must never run as the master user.
    String assertNotMaster(String userName) {
        return masterUser.equals(userName)
                ? "DENIED — master is admin-only; use a least-privilege service user"
                : "OK — dedicated least-privilege user";
    }
}

// ─── Would be in IamAuthenticator.java ───
class IamAuthenticator {
    // Short-lived token stands in for a stored password.
    String generateToken(String dbUser) {
        return "iam-token-" + dbUser + "-" + Integer.toHexString((dbUser + System.nanoTime()).hashCode());
    }
}

// ─── Would be in DbUser.java ───
class DbUser {
    private final String name;
    private final Set<String> privileges;
    DbUser(String name, Set<String> privileges) { this.name = name; this.privileges = privileges; }
    String name() { return name; }
    Set<String> privileges() { return privileges; }
    boolean can(String action) { return privileges.contains(action); }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
